se"><span class="stat-card__label">Money out</span><strong class="stat-card__value"><?=money($stats['expenses'])?></strong><span class="stat-card__note">Selected period</span></div><div class="stat-card stat-card--gold"><span class="stat-card__label">Saved so far</span><strong class="stat-card__value"><?=money($stats['savings'])?></strong><span class="stat-card__note">Across savings goals</span></div><div class="stat-card stat-card--blue"><span class="stat-card__label">Records ready</span><strong class="stat-card__value"><?=$stats['count']?></strong><span class="stat-card__note">Transactions in period</span></div></section><section class="panel" style="margin-bottom:24px;background:linear-gradient(135deg,rgba(232,163,58,.14),rgba(16,185,129,.08));"><div style="display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap;"><div><span class="eyebrow">MONEY CONFIDENCE PACK</span><h2 style="margin:7px 0 4px;">One download. A clearer conversation.</h2><p style="margin:0;color:var(--ink-soft);max-width:680px;">Start with the full personal statement. It includes your period, income, expenses, net movement and transaction history—without business noise or unnecessary detail.</p></div><a class="btn btn--accent" href="api/reports/download.php?report=statement&format=csv&from=<?=e($from)?>&to=<?=e($to)?>">Download statement CSV ↓</a></div></section><div class="report-grid" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:18px;"><?php $cards=[['statement','Personal money statement','A complete, portable overview of income, expenses, movement and the records behind it.','statement'],['transactions','Transaction history','Every recorded entry with date, description, category, payment method and reference code.','transactions'],['income','Income report','See every inflow in the selected period—useful for irregular-income proof and planning.','income'],['expenses','Expense report','Understand where money went, with category totals and a simple itemised ledger.','expenses'],['budgets','Budget pulse','Compare budgets with recorded spending and spot categories that need attention.','budgets'],['savings','Savings snapshot','See your goals, target amounts, saved amounts and progress in one portable view.','savings']];foreach($cards as [$slug,$title,$copy,$report]):?><article class="panel report-card"><div class="report-card__top"><span class="badge"><?= $slug==='statement'?'BEST START':'DOWNLOADABLE' ?></span></div><h2><?=e($title)?></h2><p><?=e($copy)?></p><div class="report-card__actions"><a class="btn btn--primary btn--small" href="api/reports/download.php?report=<?=e($report)?>&format=csv&from=<?=e($from)?>&to=<?=e($to)?>">CSV</a><a class="btn btn--quiet btn--small" href="api/reports/download.php?report=<?=e($report)?>&format=excel&from=<?=e($from)?>&to=<?=e($to)?>">Excel</a><a class="btn btn--quiet btn--small" target="_blank" href="api/reports/download.php?report=<?=e($report)?>&format=print&from=<?=e($from)?>&to=<?=e($to)?>">PDF / Print</a></div></article><?php endforeach;?></div><section class="panel" style="margin-top:24px;"><div class="panel__heading"><div><h2>Privacy by design</h2><p>Reports are generated only for your signed-in account and selected dates.</p></div></div><div class="dashboard-grid" style="gap:16px;"><div class="callout"><strong>Useful offline</strong><p>Save a CSV to your phone or share a printed copy when data is expensive or unavailable.</p></div><div class="callout"><strong>No shame, no jargon</strong><p>The report is a factual snapshot—not a judgement. It is designed to help you ask better questions and make calmer decisions.</p></div></div></section><?php require __DIR__.'/includes/footer.php'; ?><style>.report-card{display:flex;flex-direction:column;min-height:245px}.report-card p{color:var(--ink-soft);line-height:1.65;font-size:13px;flex:1}.report-card__top{display:flex;align-items:center;justify-content:space-between}.report-card__actions{display:flex;gap:8